package com.jobpilot.api.domain.community;import com.jobpilot.api.domain.admin.AdminAccessService;import java.util.UUID;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.web.server.ResponseStatusException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
@EnabledIfSystemProperty(named="review.mysql.url",matches="jdbc:mysql://127\\.0\\.0\\.1:33379/review_schema_[a-f0-9]+.*")class CommunityMysqlTest{private CommunityService s;private JdbcTemplate db;@BeforeEach void setup(){var ds=new DriverManagerDataSource(System.getProperty("review.mysql.url"),"root","");db=new JdbcTemplate(ds);var admin=mock(AdminAccessService.class);when(admin.isAdmin(anyLong())).thenReturn(false);s=new CommunityService(db,admin);}
 private CommunityService.Post post(long member,boolean privatePost,boolean feedback){return s.create(member,new CommunityService.Input("QNA","Question "+UUID.randomUUID(),"Service body",feedback,privatePost));}
 @Test void privateQuestionIsVisibleOnlyToAuthor(){var p=post(1,true,true);assertThat(s.detail(p.id(),1L).title()).isEqualTo(p.title());assertThatThrownBy(()->s.detail(p.id(),2L)).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->s.comment(p.id(),2L,null,"Unauthorized reply")).isInstanceOf(ResponseStatusException.class);assertThat(s.list("QNA",2L,0,100,"","RECENT")).noneMatch(x->x.id()==p.id());}
 @Test void feedbackAndGeneralConversationHaveSeparateAnalysisStates(){var feedback=post(1,false,true);var general=s.create(1L,new CommunityService.Input("FREE","General "+UUID.randomUUID(),"General talk",false,false));assertThat(db.queryForObject("SELECT analysis_state FROM community_posts WHERE id=?",String.class,feedback.id())).isEqualTo("PENDING");assertThat(db.queryForObject("SELECT analysis_state FROM community_posts WHERE id=?",String.class,general.id())).isEqualTo("SKIPPED");}
 @Test void viewLikeCommentAndOneLevelReplyWork(){var p=post(1,false,false);s.detail(p.id(),2L);s.detail(p.id(),2L);assertThat(s.detail(p.id(),1L).views()).isEqualTo(2);assertThat(s.like(p.id(),2L)).isTrue();assertThat(s.like(p.id(),2L)).isFalse();var c=s.comment(p.id(),2L,null,"Answer");var reply=s.comment(p.id(),1L,c.id(),"Thanks");assertThat(reply.parentId()).isEqualTo(c.id());assertThatThrownBy(()->s.comment(p.id(),1L,reply.id(),"Too deep")).isInstanceOf(ResponseStatusException.class);}
 @Test void onlyOwnerCanDelete(){var p=post(1,false,false);assertThatThrownBy(()->s.delete(p.id(),2L)).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);s.delete(p.id(),1L);assertThat(s.list("QNA",1L,0,100,"","RECENT")).noneMatch(x->x.id()==p.id());}}
